package ru.ryadom.calendar;
import org.json.*;import okhttp3.*;import biweekly.*;import biweekly.component.*;import biweekly.property.*;import java.util.*;
final class DavWrites {
 static final class Resource {String body,etag;int status;}
 static Resource request(JSONObject a,String method,String url,String body,String etag,boolean create)throws Exception{
  Request.Builder req=Providers.authenticatedRequest("yandex","",url,a.getString("login"),a.getString("password"));if(etag!=null&&!etag.isEmpty())req.header("If-Match",etag);if(create)req.header("If-None-Match","*");req.method(method,body==null?null:RequestBody.create(body,MediaType.get("text/calendar; charset=utf-8")));
  try(Response response=Providers.HTTP.newBuilder().retryOnConnectionFailure(false).build().newCall(req.build()).execute()){Resource result=new Resource();result.status=response.code();result.etag=response.header("ETag","");if(result.status==404&&method.equals("GET"))return result;if(!response.isSuccessful())throw new Providers.Failure(result.status==412?"Встреча изменилась на сервере. Обновите её перед редактированием.":"CalDAV: HTTP "+result.status+". Запись не подтверждена.",false);if(response.body()!=null){byte[] bytes=response.peekBody(2*1024*1024+1).bytes();if(bytes.length>2*1024*1024)throw new Providers.Failure("Слишком большой ответ CalDAV.",false);result.body=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);}return result;}
 }
 static Event save(JSONObject a,String calendar,Event before,Event desired,String token)throws Exception{
  String url=before==null?calendar+(calendar.endsWith("/")?"":"/")+"peklo-"+token+".ics":before.remoteUri;if(url.isEmpty())throw new Providers.Failure("Обновите календарь перед редактированием.",false);Resource old=request(a,"GET",url,null,null,false);if(before!=null&&(old.status==404||(!before.etag.isEmpty()&&!before.etag.equals(old.etag))))throw new Providers.Failure("Встреча изменилась. Обновите календарь.",false);
  ICalendar cal=old.status==404?new ICalendar():Biweekly.parse(old.body).first();if(cal==null)throw new Providers.Failure("Не удалось прочитать встречу CalDAV.",false);VEvent v;if(old.status==404){v=new VEvent();v.setUid("peklo-"+token);v.setExperimentalProperty("X-PEKLO-TOKEN",token);cal.addEvent(v);}else{if(cal.getEvents().size()!=1)throw new Providers.Failure("Серию встреч редактируйте у провайдера.",false);v=cal.getEvents().get(0);if(before==null&&(v.getExperimentalProperty("X-PEKLO-TOKEN")==null||!token.equals(v.getExperimentalProperty("X-PEKLO-TOKEN").getValue())))throw new Providers.Failure("Адрес встречи уже занят.",false);if(v.getRecurrenceRule()!=null||v.getRecurrenceId()!=null)throw new Providers.Failure("Серию встреч редактируйте у провайдера.",false);if(old.etag.isEmpty())throw new Providers.Failure("Сервер не вернул ETag: безопасная запись невозможна.",false);}
  v.setSummary(desired.title);v.setDescription(desired.description);v.setLocation(desired.location);v.setDateStart(new Date(desired.allDay?DeviceWrites.utcDay(desired.start):desired.start),!desired.allDay);v.setDateEnd(new Date(desired.allDay?DeviceWrites.utcDay(desired.end):desired.end),!desired.allDay);v.removeProperties(DurationProperty.class);v.setLastModified(new Date());v.setSequence(v.getSequence()==null?0:v.getSequence().getValue()+1);v.removeComponents(VAlarm.class);if(desired.reminderMinutes>=0)v.addAlarm(VAlarm.display(new Trigger(biweekly.util.Duration.parse("-PT"+desired.reminderMinutes+"M"),biweekly.parameter.Related.START),desired.title));
  request(a,"PUT",url,Biweekly.write(cal).go(),old.etag,old.status==404);Resource saved=request(a,"GET",url,null,null,false);Event e=Event.from(desired.json());e.source=a.optString("id");e.calendar=calendar;e.remoteUri=url;e.etag=saved.etag;e.stableId=calendar+"|"+v.getUid().getValue();e.id=e.stableId+"|"+e.start;return e;
 }
 static void delete(JSONObject a,Event e)throws Exception{if(e.remoteUri.isEmpty()||e.recurring)throw new Providers.Failure("Обновите календарь; серии удаляются у провайдера.",false);Resource old=request(a,"GET",e.remoteUri,null,null,false);if(old.status==404)return;if(old.etag.isEmpty())throw new Providers.Failure("Сервер не вернул ETag.",false);if(!e.etag.isEmpty()&&!e.etag.equals(old.etag))throw new Providers.Failure("Копия изменилась: обновите календарь.",false);request(a,"DELETE",e.remoteUri,null,old.etag,false);}
}
